(() => {
'use strict';
const D=window.UP, KEY='ultimate-pharmacist-v1', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`, link=(url,title)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`;
const fresh=()=>({version:1,province:'Ontario',theme:'system',largeText:false,gemini:false,goal:20,examDate:'',read:{},bookmarks:[],notes:{},attempts:[],osce:[],cards:{},audio:{lang:'en',index:0,positions:{},completed:[],speed:1},lastLesson:'clinical-decision-making',quiz:null,station:null,calcAttempts:0,coverage:{}});
let S=fresh(),storageOK=true;
try {const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.version===1)S=validate(saved);}catch(e){storageOK=false;}
function validate(x){const r=fresh();if(!x||x.version!==1)throw Error('This is not a supported study backup.');
if(D.provinces.some(p=>p.name===x.province))r.province=x.province;if(['light','dark','system'].includes(x.theme))r.theme=x.theme;
for(const k of ['largeText','gemini'])r[k]=!!x[k];r.goal=[10,20,30,45,60].includes(+x.goal)?+x.goal:20;r.examDate=/^\d{4}-\d{2}-\d{2}$/.test(x.examDate)?x.examDate:'';
for(const k of ['read','notes','cards'])if(x[k]&&typeof x[k]==='object')for(const l of D.lessons){const v=x[k][l.id];if(k==='notes'&&typeof v==='string')r.notes[l.id]=v.slice(0,20000);if(k==='read'&&typeof v==='number'&&v>0)r.read[l.id]=v;if(k==='cards'&&v&&Number.isFinite(v.due))r.cards[l.id]={due:v.due,interval:Number(v.interval)||1};}
r.bookmarks=Array.isArray(x.bookmarks)?x.bookmarks.filter(id=>D.lessons.some(l=>l.id===id)):[];
r.attempts=Array.isArray(x.attempts)?x.attempts.filter(a=>D.questions.some(q=>q.id===a.id)&&Number.isFinite(a.time)&&Number.isInteger(a.selected)&&a.selected>=0&&a.selected<4).slice(-3000).map(a=>({...a,correct:D.questions.find(q=>q.id===a.id).answer===a.selected})):[];
r.osce=Array.isArray(x.osce)?x.osce.filter(a=>D.stations.some(s=>s.id===a.id)&&Number.isFinite(a.time)).slice(-300):[];
if(D.lessons.some(l=>l.id===x.lastLesson))r.lastLesson=x.lastLesson;
if(x.audio&&typeof x.audio==='object'){r.audio.lang=x.audio.lang==='hi'?'hi':'en';r.audio.index=Number.isInteger(x.audio.index)&&D.audio[x.audio.index]?x.audio.index:0;r.audio.speed=[.75,1,1.25,1.5,2].includes(x.audio.speed)?x.audio.speed:1;for(const ch of D.audio)for(const lang of ['en','hi']){const k=ch.id+'-'+lang,v=x.audio.positions?.[k];if(Number.isFinite(v)&&v>=0)r.audio.positions[k]=v;}r.audio.completed=Array.isArray(x.audio.completed)?x.audio.completed.filter(k=>typeof k==='string'&&D.audio.some(ch=>k===ch.id+'-en'||k===ch.id+'-hi')):[];}
if(x.quiz&&Array.isArray(x.quiz.ids)&&x.quiz.ids.length&&x.quiz.ids.length<=D.questions.length&&x.quiz.ids.every(id=>D.questions.some(q=>q.id===id))){const v=x.quiz;r.quiz={ids:[...new Set(v.ids)],index:Math.max(0,Math.min(Number(v.index)||0,v.ids.length-1)),answers:{},checked:{},mode:v.mode==='mock'?'mock':'learn',started:Number(v.started)||Date.now(),deadline:Number(v.deadline)||null,finished:!!v.finished,fullLength:!!v.fullLength};for(const id of r.quiz.ids){if(Number.isInteger(v.answers?.[id])&&v.answers[id]>=0&&v.answers[id]<4)r.quiz.answers[id]=v.answers[id];r.quiz.checked[id]=!!v.checked?.[id];}}
if(x.station&&D.stations.some(c=>c.id===x.station.id))r.station={id:x.station.id,mode:x.station.mode==='timed'?'timed':'guided',started:Number(x.station.started)||Date.now(),deadline:Number(x.station.deadline)||null,finished:!!x.station.finished};
r.calcAttempts=Math.max(0,Number(x.calcAttempts)||0);if(x.coverage&&typeof x.coverage==='object')for(const c of D.competencies||[])for(const stage of ['Learned','Practised','MCQ','OSCE'])if(x.coverage[c.code]?.[stage]){r.coverage[c.code]??={};r.coverage[c.code][stage]=true;}return r;}
let route='',qFilter='all',studyFilter='all',searchQuery='',searchKind='all',searchTimer,toastTimer,saveTimer,flashIndex=0,flashReveal=false,calcType='volume',exercise=null,recorder=null,recordingUrl=null,recordingMime='',recordingChunks=[],audioLoaded='',sleepDeadline=0,audioQuery='',audioSubject='all';
const audio=$('#course-audio'), main=$('#main'), dialog=$('#dialog');
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));storageOK=true;$('#save-status').textContent='Saved on this device';}catch(e){storageOK=false;$('#save-status').textContent='Not saved yet';toast('Could not save. Export a backup in Settings.');}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function icons(){window.lucide?.createIcons({attrs:{width:21,height:21}});}
function modal(title,body){$('#dialog-content').innerHTML=`<div class="dialog-top"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Close">${icon('x')}</button></div>${body}`;dialog.showModal();icons();}
function close(){dialog.close();}
function applyTheme(){if(S.theme==='system')delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme=S.theme;document.documentElement.style.fontSize=S.largeText?'20px':'';}
const available=()=>D.lessons.filter(l=>l.status==='available');
const lesson=id=>D.lessons.find(l=>l.id===id);
const title=(heading,sub='',eyebrow='')=>`<div class="page-heading"><div>${eyebrow?`<span class="eyebrow">${esc(eyebrow)}</span>`:''}<h1>${esc(heading)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div></div>`;
const back=(to,label)=>`<a class="breadcrumbs" href="#${to}">${icon('chevron-left')}${esc(label)}</a>`;
const row=(to,name,sub,ic='book-open',badge='')=>`<a class="list-link" href="#${to}">${icon(ic)}<div class="grow"><h3>${esc(name)}</h3>${sub?`<p>${esc(sub)}</p>`:''}</div>${badge?`<span class="badge neutral">${esc(badge)}</span>`:icon('chevron-right')}</a>`;
const searchBox=(value='',placeholder='Search topics, drugs and more')=>`<label class="searchbox">${icon('search')}<input id="app-search" type="search" value="${esc(value)}" placeholder="${esc(placeholder)}" aria-label="Search study guide" autocomplete="off"></label>`;
function nav(){const active=route.split('/')[0];const group=['lesson','subject','search','drugs','saved','rapid','province'].includes(active)?'study':['coverage','finalweek'].includes(active)?'progress':['quiz','osce','station','calculations','flashcards','errors','official-samples'].includes(active)?'practice':active;const items=[['home','house','Home'],['study','book-open','Study'],['practice','list-checks','Practice'],['audio','headphones','Audio'],['progress','chart-no-axes-combined','Progress']];const html=items.map(([id,ic,name])=>`<a href="#${id}" ${group===id?'aria-current="page"':''}>${icon(ic)}${name}</a>`).join('');$('#bottom-nav').innerHTML=html;$('#desktop-nav').innerHTML=html;}
function home(){const l=lesson(S.lastLesson)||available()[0],done=available().filter(l=>S.read[l.id]).length;return title('A little progress, every day.','Your next step is right here.')+searchBox()+`<section class="hero-card"><span class="eyebrow">${done?'CONTINUE STUDYING':'START WITH THE FOUNDATIONS'}</span><h2>${esc(l.title)}</h2><p>${esc(l.title==='Clinical Decision Making'?'A clear approach to assessment, decisions and follow-up.':l.subject+' · '+l.minutes+' minute review')}</p><a class="button light" href="#lesson/${l.id}">${done?'Continue lesson':'Start learning'} ${icon('arrow-right')}</a></section><h2 class="section-heading">Make it a study moment</h2><div class="quick-grid">${[['practice','list-checks','Questions','Understand every answer'],['osce','messages-square','OSCE practice','Find your clinical voice'],['calculations','calculator','Calculations','Work through each step'],['audio','headphones','Listen & learn','English and Hindi']].map(([to,ic,t,s])=>`<a class="quick-card" href="#${to}">${icon(ic)}<strong>${t}</strong><span>${s}</span></a>`).join('')}</div><h2 class="section-heading">Your next steps</h2><div class="grid-two"><div class="card"><span class="muted small">Daily study goal</span><h3>${S.goal} minutes, at your pace</h3><p class="small muted">Build a routine that fits your day.</p><button class="button ghost" data-action="settings">Adjust my goal</button></div><a class="list-link" href="#flashcards">${icon('layers')}<div><h3>${dueCards().length} cards to review</h3><p>Small sessions. Lasting recall.</p></div></a></div><div class="note">${available().length} topic reviews · ${D.questions.length} original questions · ${D.stations.length} OSCE exercises. Concise educational content; independent clinical review is pending. <a href="#progress">See coverage</a></div>${row('province',S.province+' study path','Official requirements and provincial material','map-pin')}`;}
function topicRow(l){return row('lesson/'+l.id,l.title,l.status==='available'?l.subject+' · '+l.minutes+' min':'Study outline · detailed lesson in preparation',l.icon,S.read[l.id]?'Reviewed':l.status==='outline'?'Outline':'');}
function study(){let html=title('Your study library','Clear explanations. One topic at a time.')+searchBox()+`<div class="pill-tabs" aria-label="Study filter">${[['all','Subjects'],['available','Ready to study'],['saved','Saved'],['drugs','Drugs']].map(([id,t])=>`<button data-study-filter="${id}" aria-pressed="${studyFilter===id}">${t}</button>`).join('')}</div>`;
if(studyFilter==='available')return html+`<div class="stack">${available().map(topicRow).join('')}</div>`;
if(studyFilter==='saved')return html+savedContent();if(studyFilter==='drugs')return html+drugsContent();
return html+`<div class="grid-two">${D.subjects.map(s=>{const all=D.lessons.filter(l=>l.subject===s.name),n=all.filter(l=>l.status==='available').length;return row('subject/'+encodeURIComponent(s.name),s.name,`${all.length} topics · ${n} reviews`,s.icon);}).join('')}</div><div class="button-row"><a class="button secondary" href="#rapid">Quick review</a><a class="button secondary" href="#province">${esc(S.province)} pathway</a>${S.gemini?`<a class="button secondary" href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer">Open Gemini ↗</a>`:''}</div>`;}
function subject(name){const topics=D.lessons.filter(l=>l.subject===name);return back('study','Study')+title(name,`${topics.length} topics in your curriculum`)+`<div class="stack">${topics.map(topicRow).join('')}</div>`;}
function lessonPage(id){const l=lesson(id);if(!l)return notFound();S.lastLesson=id;save();const audioIndex=D.audio.findIndex(a=>a.topic===id);return back('subject/'+encodeURIComponent(l.subject),l.subject)+title(l.title,l.overview||'Use this topic outline to organize your study.')+`<div class="lesson-meta"><span class="badge">${esc(l.competency)}</span><span class="badge neutral">${l.status==='available'?'Topic review':'Study outline'}</span>${S.read[id]?'<span class="badge">Reviewed</span>':''}</div><div class="button-row"><button class="button secondary" data-action="bookmark" data-id="${id}">${icon(S.bookmarks.includes(id)?'bookmark-check':'bookmark')}${S.bookmarks.includes(id)?'Saved':'Save topic'}</button>${audioIndex>=0?`<button class="button secondary" data-listen="${audioIndex}" data-listen-lang="en">${icon('headphones')}English</button><button class="button secondary" data-listen="${audioIndex}" data-listen-lang="hi" lang="hi">हिंदी में सुनें</button>`:''}<button class="button secondary" data-action="note" data-id="${id}">${icon('notebook-pen')}My notes</button></div>${l.status==='available'?`<article class="lesson-body">${l.sections.map(s=>`<section><h2>${esc(s.title)}</h2>${s.text.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('')}</article><section class="note"><h3>Remember this</h3><ul>${l.quick.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></section><div class="button-row"><button class="button" data-action="read" data-id="${id}">${icon('check')}${S.read[id]?'Mark as not reviewed':'Mark reviewed'}</button><button class="button secondary" data-topic-quiz="${id}">Practise this topic</button></div>`:`<div class="warning"><strong>Detailed lesson in preparation.</strong> This outline is a study checklist, not a treatment guide. It does not count as completed clinical content.</div><div class="card lesson-body"><h2>Build your topic notes</h2><ul><li>Define the condition and distinguish its important alternatives.</li><li>Identify key assessment questions, relevant tests and urgent referral signs.</li><li>Compare current Canadian treatment options and patient-specific precautions.</li><li>Record monitoring, counselling, special populations and follow-up.</li><li>Use a current professional source to practise a patient case.</li></ul><a class="button secondary" href="${D.references.pebc[1]}" target="_blank" rel="noopener noreferrer">Find learning resources ↗</a></div>`}<details><summary>Further reading & content status</summary><div><p class="small">Prepared ${l.date}. Concise original study review, not a comprehensive treatment chapter. Independent clinical review is pending. The links provide further reading; they are not a claim that every statement or translation has been clinically verified. Use current Canadian references for prescribing details.</p><ul class="source-list">${l.sources.map(([t,u])=>`<li>${link(u,t)}</li>`).join('')}</ul></div></details>`;}
function savedContent(){const ids=[...new Set([...S.bookmarks,...Object.keys(S.notes).filter(k=>S.notes[k].trim())])];return ids.length?`<div class="stack">${ids.map(id=>topicRow(lesson(id))).join('')}</div>`:`<div class="empty"><h2>Keep the useful things close.</h2><p>Save a topic or add a note. It will appear here.</p></div>`;}
function drugsContent(){return `<div class="note">Study index, not a dosing reference. Open the linked lesson and verify product-specific information in the current monograph.</div><div class="stack">${D.drugs.map(d=>`<details><summary>${esc(d.name)} <span class="muted small">· ${esc(d.drugClass)}</span></summary><div><p>${esc(d.focus)}</p><div class="button-row"><a class="button secondary" href="#lesson/${d.topic}">Related lesson</a>${link(D.references.canada[1],'Health Canada monographs')}</div></div></details>`).join('')}</div>`;}
function searchPage(){return back('study','Study')+title('Find your next answer','Search inside the study guide.')+searchBox(searchQuery)+`<div class="pill-tabs">${[['all','All'],['topics','Topics'],['drugs','Drugs'],['osce','OSCE'],['questions','Questions']].map(([id,t])=>`<button data-search-filter="${id}" aria-pressed="${searchKind===id}">${t}</button>`).join('')}</div><div id="search-results">${searchResults()}</div>`;}
function searchResults(){let query=searchQuery.toLowerCase().trim();if(!query)return '<p class="muted">Try warfarin, kidney, calculations or counselling.</p>';const aliases={'blood thinner':'warfarin','coumadin':'warfarin','high blood pressure':'hypertension','kidney':'renal','inr':'warfarin','math':'calculations','high k':'electrolyte'};query=aliases[query]||query;const tokens=query.split(/\s+/);const match=s=>tokens.every(q=>s.toLowerCase().includes(q));let rows=[];
if(['all','topics'].includes(searchKind))rows.push(...D.lessons.filter(l=>match(l.title+' '+l.subject+' '+(l.overview||''))).map(topicRow));
if(['all','drugs'].includes(searchKind))rows.push(...D.drugs.filter(d=>match(d.name+' '+d.drugClass)).map(d=>row('drugs',d.name,d.drugClass,'pill')));
if(['all','osce'].includes(searchKind))rows.push(...D.stations.filter(c=>match(c.title+' '+c.scenario)).map(c=>row('station/'+c.id,c.title,'OSCE exercise','messages-square')));
if(['all','questions'].includes(searchKind))rows.push(...D.questions.filter(q=>match(q.stem+' '+lesson(q.topic).title)).slice(0,10).map(q=>row('lesson/'+q.topic,lesson(q.topic).title,'Related practice: '+q.stem,'list-checks')));
if(['all','topics'].includes(searchKind)&&/calc|dose|dilut|infus|crcl/.test(query))rows.unshift(row('calculations','Calculations lab','Dose, concentration, infusion, half-life, CrCl and research maths','calculator'));
if(['all','topics','questions'].includes(searchKind)&&/past|official|sample|previous|10 year|ten year|real question/.test(query))rows.unshift(row('official-samples','Official exam samples','Released examples; no verified ten-year archive of actual papers','files'));
return rows.length?`<p class="small muted" style="margin-bottom:14px">${rows.length} results</p><div class="stack">${rows.join('')}</div>`:`<div class="empty"><h2>No matches yet</h2><p>Try a shorter name or a related subject. Your search stays inside the app.</p></div>`;}
function provincePage(){const p=D.provinces.find(p=>p.name===S.province);return back('study','Study')+title(p.name+' study path','National learning with provincial context.')+`<div class="card"><h2>${esc(p.regulator)}</h2><p class="muted" style="margin:12px 0">Your regulator is the authority for registration, scope of practice and provincial requirements.</p>${link(p.url,'Open official regulator website')}</div><div class="note">Province selection changes your legal context. It does not establish eligibility. Choose your pathway with the regulator based on education and registration history.</div>${p.name==='Ontario'?`<div class="stack">${row('lesson/ontario-law-ethics','Ontario Law & Ethics','Introductory JEP study guide','scale')}<div class="card"><h3>Jurisprudence, Ethics & Professionalism</h3><p class="small muted" style="margin:10px 0">Use the current OCP blueprint and references alongside the law foundation questions. This app does not yet provide a comprehensive JEP course.</p>${link('https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/examination-blueprint/','OCP exam blueprint')}</div><div class="card"><h3>Practice readiness</h3><p class="small muted" style="margin:10px 0">Check whether PACE applies to your pathway. App exercises do not replace the supervised assessment.</p>${link('https://ocpinfo.com/applicants/registration-requirements/practice-assessment-of-competence-at-entry-pace/','OCP PACE guidance')}</div></div>`:p.name==='Quebec'?`<div class="warning">Quebec has a distinct OPQ registration pathway. Check equivalency and language requirements directly. The app's English/Hindi study audio does not satisfy language requirements.</div>${link('https://www.opq.org/devenir-pharmacien-au-quebec/admission/','OPQ admissions')}`:`<div class="warning">${esc(p.name)} law lessons and exam-specific questions are in preparation. Shared national lessons are available; provincial rules should be checked at the official regulator.</div>`}<div class="note"><strong>Federal law: October 2026 change</strong><p>Health Canada identifies October 1, 2026 as the transition from the current controlled-substances exemption to new regulations. Check the rules in effect on your exam or practice date alongside provincial requirements.</p><p>${link("https://www.canada.ca/en/health-canada/services/health-concerns/controlled-substances-precursor-chemicals/policy-regulations/policy-documents/section-56-1-class-exemption-patients-pharmacists-practitioners-controlled-substances-covid-19-pandemic.html","Read the official transition notice")}</p></div><h2 class="section-heading">National preparation</h2><div class="stack">${row('practice','PEBC MCQ practice','Original questions and a 200-question timed set','list-checks')}${row('osce','PEBC OSCE practice','Original guided and seven-minute exercises','messages-square')}</div><p class="small muted" style="margin-top:20px">${link('https://pebc.ca/pharmacists/new_pathway/','PEBC pathway updates')} · ${link('https://www.napra.ca/resources/pharmacy-regulatory-authorities/','Regulator directory')}</p>`;}
function rapid(){return back('study','Study')+title('Quick review','Key ideas from available lessons. Use alongside detailed study.')+`<div class="note">Final-week review highlights your mistakes and core summaries. It is not a complete seven-day preparation course.</div><div class="button-row"><button class="button" data-start-quiz="wrong">Review mistakes</button><a class="button secondary" href="#flashcards">Flashcards</a><a class="button secondary" href="#finalweek">Final 7 days</a></div><div class="stack" style="margin-top:20px">${available().map(l=>`<details><summary>${esc(l.title)}</summary><div><ul>${l.quick.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><a href="#lesson/${l.id}">Read the lesson</a></div></details>`).join('')}</div>`;}
function practice(){return title('Learn by doing.','A focused session, a clinical skill, or an exam-length practice set.')+`<div class="hero-card"><span class="eyebrow">${D.questions.length} ORIGINAL QUESTIONS</span><h2>Understand the why.</h2><p>One question at a time. Clear explanations for every choice.</p><button class="button light" data-start-quiz="mixed">Start 10 questions ${icon('arrow-right')}</button></div>${S.quiz&&!S.quiz.finished?`<div class="note">An unfinished session is saved. <a href="#quiz">Resume session</a></div>`:''}<div class="grid-two">${row('osce','OSCE practice','Guided or seven-minute stations','messages-square')}${row('calculations','Calculations lab','Units, dose maths and worked solutions','calculator')}${row('flashcards','Flashcards','Review on a spaced schedule','layers')}${row('errors','Check a prescription','Find and resolve discrepancies','scan-line')}</div><h2 class="section-heading">From the exam providers</h2>${row('official-samples','Official exam samples','Released PEBC examples and provincial resources','files')}<h2 class="section-heading">Make your own session</h2><div class="card"><div class="grid-two"><label class="field">Competency<select id="quiz-domain"><option value="all">All competencies</option>${D.domains.map(d=>`<option>${esc(d)}</option>`).join('')}</select></label><label class="field">Questions<select id="quiz-length">${[10,20,30,50].map(n=>`<option>${n}</option>`).join('')}</select></label><label class="field">Question level<select id="quiz-level"><option value="all">All levels</option><option>Foundation</option><option>Application</option><option>Challenge</option></select></label></div><div class="button-row"><button class="button" data-start-quiz="custom">Start practice</button><button class="button secondary" data-start-quiz="mock">Timed short set</button><button class="button secondary" data-start-quiz="wrong">Review mistakes</button></div></div><h2 class="section-heading">Practise the exam length</h2><div class="card"><h3>200 questions · 260 minutes</h3><p style="margin:12px 0">A single timed set drawn in the Part I blueprint proportions. Answers and explanations appear after you submit. The timer keeps running if you leave.</p><button class="button" data-start-quiz="full">Set up full-length practice</button><details><summary>See the question mix</summary><ul>${D.blueprint.map(b=>`<li>${esc(b.domain)}: ${b.count} questions (${b.mcq}%)</li>`).join('')}</ul><p>${link(D.references.blueprint[1],'Official PEBC blueprint')}. Exam timing: ${link('https://pebc.ca/faq/','PEBC FAQ')}.</p></details></div><div class="note">These are original formative questions, not official PEBC items. The bank has not been independently clinically reviewed or calibrated to PEBC difficulty. Matching length and proportions does not validate the simulation or predict a pass.</div>`;}

function officialSamples(){
 const samples='https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/part-i/sample-questions-2/';
 const sampleExam='https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/part-i/sample-exam/';
 const osce='https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/part-i-2/part-ii-format-of-examination-stations-and-sample-stations/';
 const jep='https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/sample-questions/';
 const jepPrep='https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/prepare-for-the-exam/';
 const rules='https://pebc.ca/wp-content/uploads/pdfs/Common/EN/Rules_of_Conduct_Computer-based_Examinations_at_Test_Centre.PDF';
 const resource=(badge,heading,description,url,label)=>`<section class="card"><span class="badge neutral">${badge}</span><h2 style="margin-top:12px">${heading}</h2><p style="margin:12px 0">${description}</p><a class="button secondary" href="${url}" target="_blank" rel="noopener noreferrer">${label} ${icon('external-link')}</a></section>`;
 return back('practice','Practice')+title('Official exam samples','Released examples from PEBC and your provincial regulator.')+`
 <div class="note"><strong>About the last 10 years</strong><p style="margin-top:8px">A complete, verified public collection of PEBC questions from the last ten years has not been located. PEBC requires actual examination content to remain confidential. The resources below are published samples, not complete past papers.</p><p style="margin-top:8px">${link(rules,'PEBC exam confidentiality rules')}</p></div>
 <div class="stack">
 ${resource('PEBC · Part I','Official MCQ samples','Open PEBC’s published question set and answer key. These examples illustrate question style and competencies; they do not establish the difficulty or topic balance of a complete exam.',samples,'Open PEBC MCQ samples')}
 ${resource('PEBC · Computer-based practice','Official sample exam information','PEBC’s sample exam option uses 60 questions from the published sample set. It offers practice with the testing environment; it is not an additional bank of past questions. Check the provider’s current booking conditions.',sampleExam,'See official sample exam')}
 ${resource('PEBC · Part II','Official OSCE samples','Explore five published station examples, covering patient conversations, prescription screening, product checking and a discussion with another health professional. Supporting materials and available videos stay on PEBC’s website.',osce,'Open PEBC OSCE samples')}
 ${S.province==='Ontario'?resource('Ontario · JEP','Ontario law and ethics samples','Use the College’s published sample questions and its linked demonstration tutorial to understand the question format.',jep,'Open Ontario JEP samples'):`<section class="card"><span class="badge neutral">${esc(S.province)}</span><h2 style="margin-top:12px">Your provincial exam resources</h2><p style="margin:12px 0">Provincial requirements and released samples vary. Use your selected regulator’s official pathway and preparation materials.</p><a class="button secondary" href="#province">Open ${esc(S.province)} study path</a></section>`}
 </div>
 ${S.province==='Ontario'?`<div class="note"><strong>Ontario exam date matters</strong><p style="margin-top:8px">OCP states that JEP sittings beginning October 20, 2026 will reflect the new Controlled Substances Regulations. Use resources for your exam date.</p><p style="margin-top:8px">${link(jepPrep,'Current OCP preparation guidance')}</p></div>`:''}
 <h2 class="section-heading">Use the samples in your study</h2><ol class="lesson-body"><li>Attempt the official example before reading its answer or guidance.</li><li>Identify the competency and the reasoning you need to improve.</li><li>Return to the app’s study reviews and original practice questions.</li></ol>
 <div class="button-row"><a class="button" href="#practice">My practice questions</a><a class="button secondary" href="#coverage">My competency checklist</a></div>
 <p class="small muted" style="margin-top:20px">Links checked September 19, 2026. Opens official websites in a new tab and requires internet access. Official questions are not copied into this app or included in its practice scores. Samples can change as guidance and legislation change.</p>`;
}

function shuffled(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function startQuiz(mode,topic){let bank=D.questions,domain=$('#quiz-domain')?.value||'all',count=+($('#quiz-length')?.value||10),level=$('#quiz-level')?.value||'all',full=mode==='full';if(full){count=200;for(const b of D.blueprint)if(bank.filter(q=>q.domain===b.domain).length<b.count){toast('There are not enough questions for the full blueprint mix yet.');return;}}else if(topic)bank=bank.filter(q=>q.topic===topic);else if(mode==='wrong'){const wrong=new Set(S.attempts.filter(a=>!a.correct).map(a=>a.id));bank=bank.filter(q=>wrong.has(q.id));}else if(mode==='custom'||mode==='mock'){if(domain!=='all')bank=bank.filter(q=>q.domain===domain);if(level!=='all')bank=bank.filter(q=>q.level===level);}
if(!bank.length){toast(mode==='wrong'?'No mistakes saved yet.':'No questions match that selection. Choose another level or competency.');return;}
const timed=mode==='mock'||full,create=()=>{close();const chosen=full?shuffled(D.blueprint.flatMap(b=>shuffled(bank.filter(q=>q.domain===b.domain)).slice(0,b.count))):shuffled(bank).slice(0,count);const ids=chosen.map(q=>q.id);S.quiz={ids,index:0,answers:{},checked:{},mode:timed?'mock':'learn',fullLength:full,started:Date.now(),deadline:timed?Date.now()+(full?260*60000:ids.length*78000):null,finished:false};save();go('quiz');};
const setup=()=>{pendingAction=create;modal(full?'Full-length formative practice':'Timed practice',`<p>${full?200:Math.min(count,bank.length)} questions · ${full?260:Math.round(Math.min(count,bank.length)*78/60)} minutes. The timer continues when you leave. Explanations appear after submission.</p><p style="margin-top:12px">${full?'This matches the published length and competency proportions. It is not an official or validated PEBC examination.':'This is a short formative practice set.'}</p><div class="button-row"><button class="button" data-action="confirm-pending">Start timer</button><button class="button secondary" data-action="close">Not yet</button></div>`);};
if(S.quiz&&!S.quiz.finished){pendingAction=()=>{close();if(timed)setup();else create();};modal('Replace the saved session?',`<p>Your unfinished session will be replaced. Checked answers remain in your history.</p><div class="button-row"><button class="button" data-action="confirm-pending">Replace session</button><button class="button secondary" data-action="close">Keep session</button></div>`);}else if(timed)setup();else create();}

function record(q,selected){S.attempts.push({id:q.id,selected,correct:selected===q.answer,time:Date.now(),province:S.province,mode:S.quiz?.mode||'learn'});}
function rationale(q){return `<div class="feedback"><h3>Why each option matters</h3>${q.options.map((o,i)=>`<p><strong>${String.fromCharCode(65+i)}. ${esc(o)}</strong><br><span class="small">${esc(q.explain[i])}</span></p>`).join('')}<a href="#lesson/${q.topic}">Review ${esc(lesson(q.topic).title)}</a></div>`;}
function quizPage(){const s=S.quiz;if(!s)return back('practice','Practice')+title('Start a question session')+`<a class="button" href="#practice">Choose practice</a>`;if(s.finished){const qs=s.ids.map(id=>D.questions.find(q=>q.id===id)),correct=qs.filter(q=>s.answers[q.id]===q.answer).length;return back('practice','Practice')+title('Your session, reviewed',`${correct} correct out of ${qs.length} · ${s.mode==='mock'?'Timed practice':'Learning mode'}`)+`<div class="note">This is performance on this practice set, not a prediction of your exam result.</div><div class="button-row"><button class="button" data-start-quiz="wrong">Review mistakes</button><a class="button secondary" href="#progress">See progress</a></div>${qs.map((q,i)=>`<details><summary>${i+1}. ${s.answers[q.id]===q.answer?'Correct':'Review'} · ${esc(lesson(q.topic).title)}</summary><div><p>${esc(q.stem)}</p><p class="small muted">Your answer: ${s.answers[q.id]===undefined?'Unanswered':esc(q.options[s.answers[q.id]])}</p>${rationale(q)}</div></details>`).join('')}`;}
const q=D.questions.find(q=>q.id===s.ids[s.index]),selected=s.answers[q.id],checked=s.checked[q.id];return back('practice','Practice')+`<div class="row"><span class="badge">${s.mode==='mock'?(s.fullLength?'Full-length practice':'Timed practice'):esc(q.level)}</span><span class="small">${s.index+1} of ${s.ids.length}</span>${s.deadline?`<span id="quiz-timer" class="badge"></span>`:''}</div><div class="progress-track" style="margin:17px 0 24px"><span style="width:${(s.index+1)/s.ids.length*100}%"></span></div><h2 style="line-height:1.5">${esc(q.stem)}</h2><div role="group" aria-label="Answer choices">${q.options.map((o,i)=>`<button class="answer ${checked&&i===q.answer?'correct':''} ${checked&&selected===i&&i!==q.answer?'wrong':''}" data-answer="${i}" aria-pressed="${selected===i}" ${checked?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(o)}${checked&&i===q.answer?' — Correct answer':''}</button>`).join('')}</div>${checked?rationale(q):''}<div class="button-row">${s.index>0?'<button class="button secondary" data-quiz-move="-1">Previous</button>':''}${s.mode==='learn'&&!checked?`<button class="button" data-action="check-answer" ${selected===undefined?'disabled':''}>Check answer</button>`:s.index<s.ids.length-1?'<button class="button" data-quiz-move="1">Next question</button>':'<button class="button" data-action="submit-quiz">Finish session</button>'}${s.mode==='mock'?'<button class="button secondary" data-action="submit-quiz">Submit practice exam</button>':''}</div>${s.mode==='mock'?`<div class="question-nav" aria-label="Question navigator">${s.ids.map((id,i)=>`<button data-quiz-index="${i}" class="${s.index===i?'active':''}" aria-label="Question ${i+1}, ${s.answers[id]===undefined?'unanswered':'answered'}">${i+1}${s.answers[id]===undefined?'':'✓'}</button>`).join('')}</div>`:''}`;}
function finishQuiz(){const s=S.quiz;if(!s||s.finished)return;for(const id of s.ids){const q=D.questions.find(q=>q.id===id);if(s.answers[id]!==undefined&&!s.checked[id]){record(q,s.answers[id]);s.checked[id]=true;}}s.finished=true;save();close();render();}
function submitQuiz(){const n=S.quiz.ids.filter(id=>S.quiz.answers[id]===undefined).length;pendingAction=finishQuiz;modal('Finish this session?',`<p>${n?`${n} questions are unanswered.`:'All questions have an answer.'} You can review the explanations after finishing.</p><div class="button-row"><button class="button" data-action="confirm-pending">Finish and review</button><button class="button secondary" data-action="close">Keep working</button></div>`);}
function dueCards(){return available().filter(l=>!S.cards[l.id]||S.cards[l.id].due<=Date.now());}
function flashcards(){const cards=dueCards();if(!cards.length)return back('practice','Practice')+title('You’re up to date.')+`<div class="empty"><p>Your next scheduled cards will appear here when due.</p><a class="button secondary" href="#rapid">Browse quick review</a></div>`;const l=cards[flashIndex%cards.length];return back('practice','Practice')+title('Small cards. Clear recall.',`${cards.length} due for review`)+`<div class="card flashcard"><span class="badge">${esc(l.subject)}</span><h2>${esc(l.title)}</h2>${flashReveal?`<ul style="text-align:left">${l.quick.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p class="muted">Recall the key ideas before turning the card.</p>'}<button class="button secondary" data-action="flip-card">${flashReveal?'Hide answer':'Show answer'}</button></div>${flashReveal?`<div class="button-row"><button class="button secondary" data-card-grade="1" data-id="${l.id}">Again tomorrow</button><button class="button secondary" data-card-grade="3" data-id="${l.id}">Getting there · 3 days</button><button class="button" data-card-grade="7" data-id="${l.id}">Know it · 7 days</button></div>`:''}<a class="breadcrumbs" href="#lesson/${l.id}" style="margin-top:20px">Read the lesson ${icon('arrow-right')}</a>`;}
function osce(){return title('Find your clinical voice.','Practise the conversation, then reflect on your approach.')+`<div class="note">Original exercises with self-assessment checklists. Guided mode is untimed; timed stations run for seven minutes. These are not official PEBC stations or examiner scores.</div>${S.station&&!S.station.finished?`<a class="button" href="#station/${S.station.id}">Resume current station</a>`:''}<div class="grid-two" style="margin-top:20px">${D.stations.map(c=>row('station/'+c.id,c.title,c.domain,'messages-square')).join('')}</div>`;}
function stationPage(id){const c=D.stations.find(x=>x.id===id);if(!c)return notFound();const running=S.station?.id===id,Ss=S.station;let html=back('osce','OSCE practice')+title(c.title,c.domain)+`<div class="card"><h3>Scenario</h3><p style="margin:12px 0">${esc(c.scenario)}</p><h3>Your task</h3><p style="margin-top:10px">${esc(c.task)}</p></div>`;
if(!running)return html+`<label class="field">Practice mode<select id="station-mode"><option value="guided">Guided · no timer</option><option value="timed">Timed · 7 minutes</option></select></label><button class="button" data-start-station="${id}">Start station</button>`;
if(Ss.finished)return html+`<h2 class="section-heading">Reflect on your approach</h2>${c.debrief?`<details><summary>Review the reasoning</summary><div>${c.debrief.map(t=>`<p>${esc(t)}</p>`).join('')}</div></details>`:''}<p class="small muted">Select the actions you demonstrated. This is self-assessment, not an examiner score.</p><div class="card" style="margin-top:16px">${c.check.map((t,i)=>`<label class="check-row"><input type="checkbox" data-station-check="${i}"><span>${esc(t)}</span></label>`).join('')}</div><div class="button-row"><button class="button" data-save-station="${id}">Save reflection</button><button class="button secondary" data-start-station="${id}">Practise again</button></div>${recordingUrl?`<h3 class="section-heading">Your recording</h3><audio controls src="${recordingUrl}" style="width:100%"></audio><a class="button secondary" href="${recordingUrl}" download="osce-practice.${recordingMime.includes('mp4')?'m4a':recordingMime.includes('ogg')?'ogg':'webm'}">Download recording</a><button class="button ghost" data-action="delete-recording">Delete recording</button>`:''}`;
return html+`<div class="row card" style="margin-top:20px"><div><span class="muted small">${Ss.mode==='timed'?'Time remaining':'Guided practice'}</span><div class="timer" id="station-timer">${Ss.mode==='timed'?'07:00':'Take your time'}</div></div><button class="button" data-action="finish-station">Finish & reflect</button></div><div class="button-row"><button class="button secondary" data-action="record">${icon('mic')}${recorder?.state==='recording'?'Stop recording':'Record my practice'}</button></div><p class="small muted" style="margin-top:10px">Optional recording stays in this browser until you download or delete it. Nothing is uploaded. ${Ss.mode==='timed'?'The timer continues if you leave or lock the screen.':''}</p>${Ss.mode==='guided'?`<details><summary>Show a guiding checklist</summary><div><ul>${c.check.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div></details>`:''}`;}
async function recordVoice(){if(recorder?.state==='recording'){recorder.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is unavailable here. You can still practise aloud.');return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordingChunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)recordingChunks.push(e.data);};recorder.onstop=()=>{if(recordingUrl)URL.revokeObjectURL(recordingUrl);recordingUrl=URL.createObjectURL(new Blob(recordingChunks,{type:(recordingMime=recorder.mimeType)}));stream.getTracks().forEach(t=>t.stop());toast('Recording ready. Finish the station to replay or download it.');render();};recorder.start();toast('Recording on this device. Tap Stop recording when finished.');render();}catch(e){toast('Microphone unavailable. Continue without recording.');}}
function progress(){const a=available(),read=a.filter(l=>S.read[l.id]).length,total=D.lessons.length;const first=new Map();S.attempts.forEach(x=>{if(!first.has(x.id))first.set(x.id,x);});const firsts=[...first.values()],correct=firsts.filter(a=>a.correct).length;return title('See how you’re growing.','Coverage, practice and review — each tells a different story.')+`<div class="grid-two"><div class="card"><span class="muted small">Topic reviews read</span><div class="stat-value">${read}<span class="muted" style="font-size:1rem"> / ${a.length}</span></div><div class="progress-track"><span style="width:${read/a.length*100}%"></span></div><p class="small muted" style="margin-top:10px">Reading a review is one step; apply it in cases and authoritative references.</p></div><div class="card"><span class="muted small">First-attempt accuracy</span><div class="stat-value">${firsts.length?Math.round(correct/firsts.length*100)+'%':'—'}</div><p class="small muted">${firsts.length} distinct questions attempted. ${firsts.length<10?'Not enough practice for a stable picture.':'This reflects this original practice bank.'}</p></div></div><h2 class="section-heading">Your learning record</h2><div class="grid-two"><div class="card"><h3>${S.osce.length} OSCE reflections</h3><p class="small muted">Self-assessed practice, not examiner ratings.</p></div><div class="card"><h3>${S.calcAttempts} calculation attempts</h3><p class="small muted">Practice problems checked in the lab.</p></div></div><div class="note">${a.length}/${total} topics have concise reviews and bilingual audio. This is topic availability, not complete clinical depth or proof of PEBC readiness. No pass prediction is calculated.</div><div class="button-row"><a class="button secondary" href="#coverage">My competency checklist</a><a class="button secondary" href="#finalweek">Final 7 days</a></div><h2 class="section-heading">Competency study map</h2><div class="stack">${D.domains.map(domain=>{const ls=a.filter(l=>l.competency===domain),n=ls.filter(l=>S.read[l.id]).length;const ats=firsts.filter(a=>D.questions.find(q=>q.id===a.id)?.domain===domain);return `<div class="card"><div class="row"><h3>${esc(domain)}</h3><span class="small">${n}/${ls.length} reviewed</span></div><div class="progress-track" style="margin:14px 0"><span style="width:${ls.length?n/ls.length*100:0}%"></span></div><p class="small muted">${ats.length} questions attempted · ${ats.filter(a=>a.correct).length} correct on first attempt</p></div>`;}).join('')}</div><h2 class="section-heading">Review next</h2>${reviewNext()}<div class="button-row"><a class="button" href="#rapid">Quick review</a><button class="button secondary" data-action="export">Export my progress</button></div><details><summary>What is still in preparation?</summary><div><p>Comprehensive clinical chapters and reviewed dose tables; independently reviewed and calibrated exam banks; complete provincial law courses; native Siri playback integration and physical-iPhone validation.</p><p class="small muted" style="margin-top:10px">All-topic reviews and audio are available. This does not complete the originally planned detailed, clinically reviewed exam course.</p></div></details>`;}
function coveragePage(){return back('progress','Progress')+title('Your competency checklist','Use the official blueprint alongside your own evidence of practice.')+`<div class="note">These are your self-recorded checkpoints. A tick means you have worked on that activity; it is not an examiner rating or verified competence. ${link(D.references.blueprint[1],'Read the official PEBC blueprint')}.</div><div class="stack">${D.competencies.map(c=>`<div class="card"><h3>${c.code} · ${esc(c.label)}</h3><p class="small muted">${esc(c.domain)}</p><div class="checklist-stages">${['Learned','Practised','MCQ','OSCE'].map(stage=>`<label class="check-row"><input type="checkbox" data-competency="${c.code}" data-stage="${stage}" ${S.coverage[c.code]?.[stage]?'checked':''}><span>${stage}</span></label>`).join('')}</div></div>`).join('')}</div>`;}
function finalWeek(){const days=[['Day 1 · Find the gaps','Review first-attempt mistakes and your competency checklist. Choose three priorities.','coverage','Open checklist'],['Day 2 · Clinical decisions','Review assessment, red flags and monitoring across your weakest clinical subjects.','study','Open study library'],['Day 3 · Distribution and calculations','Practise prescription verification, preparation checks and unit-aware calculations.','calculations','Open calculations'],['Day 4 · Communication and OSCE','Run timed counselling and prescriber-call stations. Reflect on actions you actually demonstrated.','osce','Open OSCE practice'],['Day 5 · Ethics, law and evidence','Use current federal and provincial resources, then practise evidence interpretation.','province','Open provincial pathway'],['Day 6 · Timed practice and review','Use the full-length formative set if useful. Review reasoning and fatigue patterns afterwards.','practice','Open practice'],['Day 7 · Consolidate and prepare','Use short audio reviews, confirm exam logistics and make time for rest. Avoid treating a practice percentage as a pass prediction.','audio','Open audio']];return back('progress','Progress')+title('Your final 7 days','A flexible revision plan, not a seven-day substitute for preparation.')+`<div class="note">Adjust this plan to your exam date, accommodations and existing preparation. Prioritize unresolved safety and knowledge gaps.</div><div class="stack">${days.map(([h,t,to,b])=>`<section class="card"><h2>${h}</h2><p style="margin:12px 0">${t}</p><a class="button secondary" href="#${to}">${b}</a></section>`).join('')}</div>`;}
function reviewNext(){const wrong={};S.attempts.filter(a=>!a.correct).forEach(a=>{const q=D.questions.find(q=>q.id===a.id);wrong[q.topic]=(wrong[q.topic]||0)+1;});const keys=Object.keys(wrong).sort((a,b)=>wrong[b]-wrong[a]).slice(0,3);return keys.length?`<div class="stack">${keys.map(id=>row('lesson/'+id,lesson(id).title,`${wrong[id]} incorrect attempts · revisit the explanation`,'rotate-ccw')).join('')}</div>`:'<p class="muted">Practice results will help you choose what to revisit.</p>';}
function settings(){modal('Make it yours',`<label class="field">Appearance<select id="setting-theme"><option value="system" ${S.theme==='system'?'selected':''}>Match my iPhone</option><option value="light" ${S.theme==='light'?'selected':''}>Light</option><option value="dark" ${S.theme==='dark'?'selected':''}>Dark</option></select></label><label class="check-row"><input id="setting-large" type="checkbox" ${S.largeText?'checked':''}><span>Larger reading text</span></label><label class="field">Daily goal<select id="setting-goal">${[10,20,30,45,60].map(n=>`<option ${S.goal===n?'selected':''} value="${n}">${n} minutes</option>`).join('')}</select></label><label class="field">Exam date (optional)<input id="setting-date" type="date" value="${esc(S.examDate)}"></label><label class="check-row"><input id="setting-gemini" type="checkbox" ${S.gemini?'checked':''}><span>Show optional Gemini link<small class="muted" style="display:block">Opens Gemini separately. Notes and searches are not sent automatically.</small></span></label><div class="button-row"><button class="button" data-action="save-settings">Save preferences</button><button class="button secondary" data-action="siri">Siri & iPhone setup</button></div><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3>Your progress belongs to you</h3><p class="small muted">Stored in this browser, not synced between devices. Export a backup before clearing browser data.</p><div class="button-row"><button class="button secondary" data-action="export">Export backup</button><label class="button secondary">Import backup<input id="import-file" type="file" accept="application/json,.json" class="sr-only"></label><button class="button ghost" data-action="reset">Reset progress</button></div>`);}
function siri(){const base=location.href.split('#')[0];modal('On your iPhone',`<h3>Add to Home Screen</h3><p class="small" style="margin:10px 0 20px">Open this app in Safari. Tap Share, then Add to Home Screen. Your app opens with its own icon.</p><h3>Siri shortcuts</h3><ol class="small"><li>Open Apple Shortcuts and create a shortcut.</li><li>Add the URL below, then an Open URLs action.</li><li>Name it “Open Pharmacist” or “Pharmacist Hindi Audio”.</li><li>Ask Siri to run that shortcut by name.</li></ol><label class="field">App link<input readonly value="${esc(base+'#home')}"></label><label class="field">Hindi audio link<input readonly value="${esc(base+'#audio/hi')}"></label><button class="button secondary" data-copy="${esc(base+'#audio/hi')}">Copy Hindi audio link</button><div class="note">These shortcuts open the app or course. Safari may require a tap to start playback. Direct Siri playback commands require native integration and are not included in this web release.</div>`);}
function exportData(){const blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ultimate-pharmacist-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it somewhere safe.');}
async function importData(file){if(!file)return;if(file.size>5000000){toast('Backup is too large. Choose a file under 5 MB.');return;}try{const next=validate(JSON.parse(await file.text()));pendingAction=()=>{S=next;save();applyTheme();$('#province').value=S.province;close();render();toast('Backup restored.');};close();modal('Restore this backup?',`<p>This replaces progress and notes on this device with the selected backup.</p><div class="button-row"><button class="button" data-action="confirm-pending">Restore backup</button><button class="button secondary" data-action="close">Cancel</button></div>`);}catch(e){toast('That file is not a valid Ultimate Pharmacist backup.');}}
function notFound(){return title('Let’s get you back on track.')+`<a href="#home" class="button">Go Home</a>`;}
function go(to){if(location.hash==='#'+to)render();else location.hash=to;}
let pendingAction=null;
function render(){route=decodeURI(location.hash.slice(1)||'home');const [screen,...rest]=route.split('/');const id=rest.join('/');let content;switch(screen){case 'home':content=home();break;case 'study':content=study();break;case 'subject':content=subject(decodeURIComponent(id));break;case 'lesson':content=lessonPage(id);break;case 'search':content=searchPage();break;case 'saved':content=back('study','Study')+title('Saved for you')+savedContent();break;case 'drugs':content=back('study','Study')+title('Drug study library')+drugsContent();break;case 'province':content=provincePage();break;case 'rapid':content=rapid();break;case 'practice':content=practice();break;case 'official-samples':content=officialSamples();break;case 'quiz':content=quizPage();break;case 'flashcards':content=flashcards();break;case 'osce':content=osce();break;case 'station':content=stationPage(id);break;case 'calculations':content=calculations();break;case 'errors':content=errorsPage();break;case 'progress':content=progress();break;case 'coverage':content=coveragePage();break;case 'finalweek':content=finalWeek();break;case 'audio':if(['en','hi'].includes(id)&&S.audio.lang!==id){audio.pause();audioLoaded='';S.audio.lang=id;save();}content=audioPage();break;default:content=notFound();}
main.innerHTML=content;nav();mini();icons();tick();document.title=(screen==='home'?'Ultimate Pharmacist':screen.charAt(0).toUpperCase()+screen.slice(1)+' · Ultimate Pharmacist');}
// Calculations are fictional teaching tools, not a clinical dosing service.
const CALCS={
volume:{name:'Dose → volume',fields:[['dose','Required amount','mg',150],['strength','Drug amount on label','mg',100],['volume','Label volume','mL',5]],unit:'mL',run:v=>({value:v.dose*v.volume/v.strength,steps:`Concentration = ${v.strength} mg ÷ ${v.volume} mL = ${fmt(v.strength/v.volume)} mg/mL. Volume = ${v.dose} mg ÷ concentration.`,formula:'Volume = required amount × label volume ÷ label amount'})},
weight:{name:'Weight-based dose',fields:[['weight','Body weight','kg',20],['dose','Specified dose per administration','mg/kg/dose',5]],unit:'mg/dose',run:v=>({value:v.weight*v.dose,steps:`${v.weight} kg × ${v.dose} mg/kg/dose. This is one dose; it is not a daily total.`,formula:'Amount per dose = weight × specified mg/kg/dose'})},
dilution:{name:'Dilution',fields:[['initial','Stock concentration','mg/mL',10],['final','Desired concentration','mg/mL',2],['volume','Final total volume','mL',100]],unit:'mL stock',run:v=>{if(v.final>v.initial)throw Error('Desired concentration cannot exceed stock concentration in this dilution exercise.');const value=v.final*v.volume/v.initial;return {value,steps:`C₁V₁ = C₂V₂. Use ${fmt(value)} mL stock and dilute to a total volume of ${v.volume} mL (not add ${v.volume} mL).`,formula:'Stock volume = desired concentration × final volume ÷ stock concentration'};}},
infusion:{name:'Infusion rate',fields:[['volume','Total volume','mL',500],['hours','Infusion duration','hours',4]],unit:'mL/hour',run:v=>({value:v.volume/v.hours,steps:`${v.volume} mL ÷ ${v.hours} hours. This calculates a rate from a fictional order, not a recommended patient regimen.`,formula:'Rate = volume ÷ time'})},
days:{name:'Days supply',fields:[['quantity','Quantity supplied','tablets',60],['dose','Tablets per dose','tablets',1],['frequency','Doses per day','per day',2]],unit:'days',run:v=>({value:v.quantity/(v.dose*v.frequency),steps:`Daily use = ${v.dose} × ${v.frequency} = ${v.dose*v.frequency} tablets/day. ${v.quantity} tablets ÷ daily use.`,formula:'Days supply = quantity ÷ daily use'})},
half:{name:'Half-life model',fields:[['amount','Initial model amount','mg',80],['half','Half-life','hours',6],['time','Elapsed time','hours',18]],unit:'mg remaining',run:v=>({value:v.amount*Math.pow(.5,v.time/v.half),steps:`${v.time} ÷ ${v.half} = ${fmt(v.time/v.half)} half-lives. Multiply ${v.amount} mg by (1/2) to that power. Assumes first-order elimination.`,formula:'Remaining amount = initial amount × (1/2)^(time ÷ half-life)'})},
nnt:{name:'Risk reduction & NNT',fields:[['control','Control event risk','%',10],['treatment','Treatment event risk','%',6]],unit:'people (NNT)',run:v=>{if(v.control>100||v.treatment>100)throw Error('Event risks must be between 0 and 100%.');if(v.control<=v.treatment)throw Error('This NNT exercise requires treatment risk below control risk. Equal risk has no finite NNT; higher risk requires a harm calculation.');const arr=(v.control-v.treatment)/100;return {value:Math.ceil(1/arr),steps:`ARR = ${fmt(v.control-v.treatment)} percentage points = ${fmt(arr)}. NNT = 1 ÷ ${fmt(arr)}, rounded up. Attach the study timeframe and outcome.`,formula:'NNT = 1 ÷ absolute risk reduction as a proportion'};}},
bsa:{name:'Body surface area',fields:[['height','Height','cm',170],['weight','Weight','kg',70]],unit:'m²',run:v=>({value:Math.sqrt(v.height*v.weight/3600),steps:`Mosteller model: square root of (${v.height} cm × ${v.weight} kg ÷ 3600). Drug protocols may specify other methods.`,formula:'BSA = √(height in cm × weight in kg ÷ 3600)'})},
crcl:{name:'Creatinine clearance model',fields:[['age','Adult age','years',65],['weight','Model dosing weight','kg',70],['scr','Serum creatinine','µmol/L',100]],unit:'mL/min',run:v=>{if(v.age<18||v.age>=140)throw Error('Use an adult teaching age between 18 and 139 years.');const factor=+($('#calc-factor')?.value||1);return {value:(140-v.age)*v.weight/(72*(v.scr/88.4))*factor,steps:`Convert creatinine to mg/dL: ${v.scr} ÷ 88.4. Calculate (140 − age) × weight ÷ (72 × creatinine in mg/dL), then multiply by ${factor}. Conventional Cockcroft–Gault model; unstable function, body size and dialysis need additional assessment.`,formula:'CrCl = (140 − age) × weight ÷ (72 × creatinine in mg/dL) × equation factor'};}}
};
function fmt(n){return Number(n.toFixed(3)).toLocaleString('en-CA',{maximumFractionDigits:3});}
function calculations(){const c=CALCS[calcType];return back('practice','Practice')+title('Every step, made clear.','Learn the method. Keep the units attached.')+`<div class="note">Fictional learning exercises only. These tools do not recommend or verify a patient dose.</div><label class="field">Calculation<select id="calc-type">${Object.entries(CALCS).map(([id,x])=>`<option value="${id}" ${id===calcType?'selected':''}>${x.name}</option>`).join('')}</select></label><div class="card"><h2>${c.name}</h2><form id="calculator-form"><div class="grid-two">${c.fields.map(([id,label,unit,value])=>`<label class="field">${label} (${unit})<input required inputmode="decimal" type="text" id="calc-${id}" value="${value}" aria-label="${label} in ${unit}"></label>`).join('')}</div>${calcType==='crcl'?`<label class="field">Conventional equation factor<select id="calc-factor"><option value="1">1.0</option><option value="0.85">0.85 (conventional female coefficient)</option></select></label><p class="small muted">The historical coefficient describes the equation, not a gender identity assessment. This model is not valid for every patient.</p>`:''}<button class="button" type="submit">Show worked solution</button></form><div id="calculation-result" aria-live="polite"></div></div><h2 class="section-heading">Try a practice problem</h2><div class="card" id="exercise-card">${exerciseContent()}</div>`;}
function solveCalculation(){const c=CALCS[calcType],v={};try{for(const [id,label]of c.fields){const s=$('#calc-'+id).value.trim();if(!/^\d+(\.\d+)?$/.test(s))throw Error('Enter a valid number for '+label+'.');v[id]=Number(s);if(!Number.isFinite(v[id])||v[id]<0||v[id]===0&&!['time','control','treatment'].includes(id))throw Error(label+' must be greater than zero.');}const result=c.run(v);if(!Number.isFinite(result.value))throw Error('These inputs do not produce a valid result.');$('#calculation-result').innerHTML=`<div class="feedback"><div class="stat-value">${fmt(result.value)} <span style="font-size:1rem">${c.unit}</span></div><p>${esc(result.formula)}</p><p class="small">${esc(result.steps)}</p><p class="small muted">Displayed to at most 3 decimal places unless a whole-number rule applies. Follow the required rounding for the task.</p></div>`;}catch(e){$('#calculation-result').innerHTML=`<p class="warning" role="alert">${esc(e.message)}</p>`;}}
function newExercise(){const type=Math.floor(Math.random()*4),n=1+Math.floor(Math.random()*8);exercise=type===0?{text:`A fictional liquid contains ${n*25} mg in 5 mL. What volume contains ${n*50} mg?`,answer:10,unit:'mL',why:`(${n*50} mg × 5 mL) ÷ ${n*25} mg = 10 mL.`}:type===1?{text:`A fictional order supplies 600 mL over ${n+2} hours. Calculate mL/hour to 2 decimal places.`,answer:600/(n+2),unit:'mL/hour',why:`600 mL ÷ ${n+2} hours = ${fmt(600/(n+2))} mL/hour.`}:type===2?{text:`A fictional order gives 2 tablets ${n%3+1} times per day. ${30*(n%3+1)} tablets are supplied. How many days will they last?`,answer:15,unit:'days',why:`${30*(n%3+1)} ÷ (2 × ${n%3+1}) = 15 days.`}:{text:`A first-order model starts with ${n*80} mg. How much remains after 3 half-lives?`,answer:n*10,unit:'mg',why:`${n*80} × (1/2)³ = ${n*10} mg.`};}
function exerciseContent(){if(!exercise)newExercise();return `<p>${esc(exercise.text)}</p><form id="exercise-form"><div class="grid-two"><label class="field">Your answer<input id="exercise-answer" inputmode="decimal" required></label><label class="field">Unit<select id="exercise-unit"><option value="">Choose unit</option>${['mg','mL','mL/hour','days'].map(u=>`<option>${u}</option>`).join('')}</select></label></div><div class="button-row"><button class="button" type="submit">Check answer</button><button class="button secondary" type="button" data-action="new-exercise">New problem</button></div></form><div id="exercise-feedback" aria-live="polite"></div>`;}
const ERROR_CASES=[{title:'Check the strength',rx:'Fictional order: Product A, 10 mg tablets. Take ONE tablet daily. Quantity: 30.',label:'Prepared label: Product A, 20 mg tablets. Take ONE tablet daily. Quantity: 30.',options:['Wrong strength','Wrong quantity','Wrong frequency','No discrepancy'],answer:0,why:'The dispensed label states 20 mg while the order states 10 mg. Hold the affected step, verify against the original order and resolve before supply.'},{title:'Check the directions',rx:'Fictional order: Product B. Take ONE capsule twice daily for 5 days. Quantity: 10.',label:'Prepared label: Product B. Take TWO capsules twice daily for 5 days. Quantity: 10.',options:['No discrepancy','Wrong directions','Wrong expiry','Wrong patient'],answer:1,why:'The label doubles each dose. Confirm the original instructions and correct the discrepancy through the checking process.'},{title:'Check the patient',rx:'Fictional order for Alex Martin, date of birth 1990-04-12.',label:'Prepared label for Alex Martin, date of birth 1981-08-21.',options:['Wrong route','No discrepancy','Patient identity mismatch','Wrong dosage form'],answer:2,why:'Matching names are not sufficient. The dates of birth differ; establish the correct patient before proceeding.'},{title:'Check the quantity',rx:'Fictional order: Product C. Take ONE tablet twice daily for 7 days. Quantity: 14.',label:'Prepared package: 7 tablets. Directions match the order.',options:['Quantity does not match the order','Wrong route','Wrong timing','No discrepancy'],answer:0,why:'Two tablets per day for seven days requires 14 tablets. Verify and correct the quantity; do not silently shorten the course.'}];
let errorIndex=0,errorAnswered=false;
function errorsPage(){const c=ERROR_CASES[errorIndex];return back('practice','Practice')+title('Catch the discrepancy.','A fictional final-check exercise.')+`<p class="small muted">Case ${errorIndex+1} of ${ERROR_CASES.length}</p><h2 class="section-heading">${c.title}</h2><div class="grid-two"><div class="card"><h3>Original order</h3><p style="margin-top:12px">${c.rx}</p></div><div class="card"><h3>Prepared product</h3><p style="margin-top:12px">${c.label}</p></div></div><h3 class="section-heading">What needs attention?</h3>${c.options.map((o,i)=>`<button class="answer" data-error-answer="${i}" ${errorAnswered?'disabled':''}>${o}</button>`).join('')}<div id="error-feedback" aria-live="polite"></div>${errorAnswered?`<button class="button" data-action="next-error">Next case</button>`:''}`;}
function audioPage(){const ch=D.audio[S.audio.index],lang=S.audio.lang,has=!!ch.files[lang],total=D.audio.reduce((n,a)=>n+(a.duration[lang]||0),0),position=audioLoaded===ch.id+'-'+lang?audio.currentTime:(S.audio.positions[ch.id+'-'+lang]||0);return title('Your listening space','Every topic, in English and Hindi. Keep your place as you go.')+`<div class="pill-tabs" aria-label="Audio language"><button data-audio-lang="en" aria-pressed="${lang==='en'}">English</button><button data-audio-lang="hi" aria-pressed="${lang==='hi'}" lang="hi">हिंदी</button></div><div class="album"><span class="eyebrow">ALL-TOPIC REVIEW · ${lang==='hi'?'HINDI':'ENGLISH'}</span><h2>${esc(ch.title)}</h2><span class="small">Chapter ${S.audio.index+1} of ${D.audio.length} · ${Math.round(total/60)} minutes in this language</span></div><div style="margin-top:18px"><label class="sr-only" for="audio-seek">Audio position</label><input id="audio-seek" class="range" type="range" min="0" max="${ch.duration[lang]||1}" value="${position}" step="1"><div class="row small muted"><span id="audio-elapsed">${clock(position)}</span><span>${clock(ch.duration[lang]||0)}</span></div></div><div class="player-controls"><button data-action="audio-prev" aria-label="Previous chapter">${icon('skip-back')}</button><button data-action="audio-back" aria-label="Back 15 seconds">${icon('rotate-ccw')}</button><button class="play-main" data-action="audio-play" aria-label="${audio.paused?'Play':'Pause'}">${icon(audio.paused?'play':'pause')}</button><button data-action="audio-forward" aria-label="Forward 15 seconds">${icon('rotate-cw')}</button><button data-action="audio-next" aria-label="Next chapter">${icon('skip-forward')}</button></div>${!has?'<div class="warning">This recording is unavailable. The transcript remains below.</div>':''}<div class="grid-two"><label class="field">Playback speed<select id="audio-speed">${[.75,1,1.25,1.5,2].map(v=>`<option value="${v}" ${S.audio.speed===v?'selected':''}>${v}×</option>`).join('')}</select></label><label class="field">Sleep timer<select id="audio-sleep"><option value="0">Off</option><option value="10">10 minutes</option><option value="20">20 minutes</option><option value="30">30 minutes</option></select></label></div><p id="sleep-status" class="small muted">${sleepDeadline?'Sleep timer is running.':''}</p><details><summary>Read this transcript</summary><div class="lesson-body" ${lang==='hi'?'lang="hi"':''}><p>${esc(ch[lang])}</p><a href="#lesson/${ch.topic}">Open the study review</a></div></details><div class="button-row"><button class="button secondary" data-action="siri">Siri & iPhone setup</button>${has?`<a class="button secondary" href="${ch.files[lang]}" download>Download this chapter</a>`:''}</div><h2 class="section-heading">Find a chapter</h2><label class="searchbox">${icon('search')}<input id="audio-filter" type="search" placeholder="Search all ${D.audio.length} audio chapters" aria-label="Search audio chapters" value="${esc(audioQuery)}"></label><label class="field">Subject<select id="audio-subject"><option value="all">All subjects</option>${D.subjects.map(x=>`<option ${audioSubject===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div id="chapter-list">${audioList()}</div><div class="note">${D.audio.length} concise topic reviews in both languages, with synthetic narration. Hindi explains the core ideas and is not a word-for-word translation. These recordings are revision material, not a complete detailed PEBC course; independent clinical and language review is pending. Continuous playback follows the full chapter order, regardless of the display filter.</div>`;}
function audioList(){const lang=S.audio.lang,items=D.audio.map((a,i)=>({a,i})).filter(({a})=>(audioSubject==='all'||a.subject===audioSubject)&&a.title.toLowerCase().includes(audioQuery.toLowerCase().trim()));if(!items.length)return '<p class="muted">No chapters match. Try a shorter search or another subject.</p>';return D.subjects.map(x=>{const part=items.filter(({a})=>a.subject===x.name);if(!part.length)return '';return `<details ${audioQuery||audioSubject!=='all'||part.some(({i})=>i===S.audio.index)?'open':''}><summary>${esc(x.name)} <span class="muted small">${part.length} chapters</span></summary><div>${part.map(({a,i})=>`<button class="list-link" data-audio-index="${i}" style="text-align:left;width:100%">${icon(i===S.audio.index?'headphones':'play')}<div class="grow"><h3>${i+1}. ${esc(a.title)}</h3><p>${a.files[lang]?clock(a.duration[lang]):'Unavailable'}${S.audio.completed.includes(a.id+'-'+lang)?' · Listened':''}</p></div>${i===S.audio.index?'<span class="badge">Selected</span>':''}</button>`).join('')}</div></details>`;}).join('');}

function clock(s){s=Math.max(0,Math.floor(s));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function mini(){const ch=D.audio[S.audio.index];if(!audioLoaded){$('#mini-player').innerHTML='';return;}$('#mini-player').innerHTML=`<div class="mini">${icon('headphones')}<a href="#audio">${esc(ch.title)}<small>${S.audio.lang==='hi'?'हिंदी':'English'} · ${audio.paused?'Paused':'Playing'}</small></a><button class="icon-button" data-action="audio-play" aria-label="${audio.paused?'Play':'Pause'} audio">${icon(audio.paused?'play':'pause')}</button></div>`;}
async function playAudio(){const ch=D.audio[S.audio.index],lang=S.audio.lang,key=ch.id+'-'+lang;if(!ch.files[lang]){toast('This recording is not available yet.');return;}if(audioLoaded!==key){audio.pause();const resumeAt=S.audio.positions[key]||0;audioLoaded=key;audio.src=ch.files[lang];audio.playbackRate=S.audio.speed;audio.addEventListener('loadedmetadata',()=>{audio.currentTime=Math.min(resumeAt,Math.max(0,audio.duration-1));},{once:true});}else if(!audio.paused){audio.pause();refreshPlayer();return;}try{await audio.play();setMedia();refreshPlayer();}catch(e){toast('Playback could not start. Tap Play to retry, or check your connection.');}}
function setMedia(){if(!('mediaSession'in navigator))return;const ch=D.audio[S.audio.index];navigator.mediaSession.metadata=new MediaMetadata({title:ch.title,artist:'Ultimate Pharmacist',album:S.audio.lang==='hi'?'Hindi topic reviews':'English topic reviews',artwork:[{src:new URL('icon-512.png',location.href).href,sizes:'512x512',type:'image/png'}]});for(const [action,fn]of Object.entries({play:()=>audio.play().catch(()=>{}),pause:()=>audio.pause(),previoustrack:()=>changeChapter(-1),nexttrack:()=>changeChapter(1),seekbackward:()=>{audio.currentTime=Math.max(0,audio.currentTime-15);},seekforward:()=>{audio.currentTime=Math.min(audio.duration||0,audio.currentTime+15);}})){try{navigator.mediaSession.setActionHandler(action,fn);}catch(e){}}}
function refreshPlayer(){mini();if(route.startsWith('audio')){document.querySelectorAll('[data-action="audio-play"]').forEach(b=>{b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-label',audio.paused?'Play audio':'Pause audio');});}icons();}
function changeChapter(delta){const next=S.audio.index+delta;if(next<0||next>=D.audio.length){audio.pause();toast(next<0?'You are at the first chapter.':'You have reached the end of the review course.');refreshPlayer();return;}audio.pause();S.audio.index=next;audioLoaded='';save();if(route.startsWith('audio'))render();playAudio();}
audio.addEventListener('timeupdate',()=>{if(!audioLoaded)return;S.audio.positions[audioLoaded]=audio.currentTime;if($('#audio-elapsed'))$('#audio-elapsed').textContent=clock(audio.currentTime);if($('#audio-seek'))$('#audio-seek').value=audio.currentTime;if(Math.floor(audio.currentTime)%5===0)save();});
audio.addEventListener('ended',()=>{if(!S.audio.completed.includes(audioLoaded))S.audio.completed.push(audioLoaded);save();changeChapter(1);});audio.addEventListener('pause',()=>{if(audioLoaded){S.audio.positions[audioLoaded]=audio.currentTime;save();}refreshPlayer();});audio.addEventListener('play',refreshPlayer);audio.addEventListener('error',()=>{toast('Audio could not load. Check your connection, then retry.');refreshPlayer();});
function tick(){const now=Date.now();if(S.quiz&&!S.quiz.finished&&S.quiz.deadline){const left=Math.max(0,(S.quiz.deadline-now)/1000);if($('#quiz-timer'))$('#quiz-timer').textContent=clock(left);if(left<=0){finishQuiz();toast('Time is up. Your saved answers have been submitted.');}}
if(S.station&&!S.station.finished&&S.station.deadline){const left=Math.max(0,(S.station.deadline-now)/1000);if($('#station-timer'))$('#station-timer').textContent=clock(left);if(left<=0){S.station.finished=true;if(recorder?.state==='recording')recorder.stop();save();if(route.startsWith('station'))render();toast('Seven minutes complete. Time to reflect.');}}
if(sleepDeadline&&now>=sleepDeadline){audio.pause();sleepDeadline=0;if($('#sleep-status'))$('#sleep-status').textContent='Sleep timer finished.';toast('Sleep timer finished. Audio paused.');}}
setInterval(tick,1000);
$('#province').innerHTML=D.provinces.map(p=>`<option ${p.name===S.province?'selected':''}>${esc(p.name)}</option>`).join('');
$('#province').addEventListener('change',e=>{const value=e.target.value;if(S.quiz&&!S.quiz.finished&&S.quiz.mode==='mock'||S.station&&!S.station.finished){e.target.value=S.province;toast('Finish the active exam or station before changing province.');return;}S.province=value;save();render();toast('Study path changed to '+value+'. Your progress is preserved.');});
document.addEventListener('input',e=>{if(e.target.id==='app-search'){searchQuery=e.target.value;clearTimeout(searchTimer);if(route==='search'){searchTimer=setTimeout(()=>{$('#search-results').innerHTML=searchResults();icons();},100);}else{searchTimer=setTimeout(()=>{go('search');setTimeout(()=>{const box=$('#app-search');box?.focus();box?.setSelectionRange(searchQuery.length,searchQuery.length);},20);},300);}}if(e.target.id==='audio-filter'){audioQuery=e.target.value;$('#chapter-list').innerHTML=audioList();icons();}if(e.target.id==='lesson-note'){const id=e.target.dataset.id;S.notes[id]=e.target.value;clearTimeout(saveTimer);saveTimer=setTimeout(save,300);}if(e.target.id==='audio-seek'&&audioLoaded)audio.currentTime=Number(e.target.value);});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.competency){S.coverage[el.dataset.competency]??={};S.coverage[el.dataset.competency][el.dataset.stage]=el.checked;save();}if(el.id==='audio-subject'){audioSubject=el.value;$('#chapter-list').innerHTML=audioList();icons();}if(el.id==='calc-type'){calcType=el.value;render();}if(el.id==='audio-speed'){S.audio.speed=Number(el.value);audio.playbackRate=S.audio.speed;save();}if(el.id==='audio-sleep'){sleepDeadline=Number(el.value)?Date.now()+Number(el.value)*60000:0;$('#sleep-status').textContent=sleepDeadline?'Audio will pause in '+el.value+' minutes.':'Sleep timer off.';}if(el.id==='import-file')importData(el.files[0]);});
document.addEventListener('submit',e=>{if(e.target.id==='calculator-form'){e.preventDefault();solveCalculation();}if(e.target.id==='exercise-form'){e.preventDefault();const raw=$('#exercise-answer').value.trim(),unit=$('#exercise-unit').value;if(!/^\d+(\.\d+)?$/.test(raw)||!unit){$('#exercise-feedback').innerHTML='<p class="warning" role="alert">Enter a number and choose its unit.</p>';return;}const correct=Math.abs(Number(raw)-exercise.answer)<=.011&&unit===exercise.unit;S.calcAttempts++;save();$('#exercise-feedback').innerHTML=`<div class="feedback"><h3>${correct?'Correct — units included.':'Let’s work through it.'}</h3><p>${exercise.why}</p>${unit!==exercise.unit?`<p>The required unit is ${exercise.unit}.</p>`:''}</div>`;}});
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();main.scrollIntoView();return;}const b=e.target.closest('button,[data-copy]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
if(b.dataset.studyFilter){studyFilter=b.dataset.studyFilter;render();}if(b.dataset.searchFilter){searchKind=b.dataset.searchFilter;render();}
if(b.dataset.startQuiz)startQuiz(b.dataset.startQuiz);if(b.dataset.topicQuiz)startQuiz('topic',b.dataset.topicQuiz);
if(b.dataset.answer!==undefined&&S.quiz){const s=S.quiz,q=D.questions.find(q=>q.id===s.ids[s.index]);if(!s.checked[q.id]){s.answers[q.id]=Number(b.dataset.answer);save();render();}}
if(b.dataset.quizMove){S.quiz.index=Math.max(0,Math.min(S.quiz.ids.length-1,S.quiz.index+Number(b.dataset.quizMove)));save();render();main.focus();}
if(b.dataset.quizIndex!==undefined){S.quiz.index=Number(b.dataset.quizIndex);save();render();}
if(b.dataset.cardGrade){S.cards[id]={due:Date.now()+Number(b.dataset.cardGrade)*86400000,interval:Number(b.dataset.cardGrade)};save();flashReveal=false;render();}
if(b.dataset.startStation){if(S.station&&!S.station.finished&&S.station.id!==b.dataset.startStation){toast('Finish your current station first.');return;}S.station={id:b.dataset.startStation,mode:$('#station-mode')?.value||'guided',started:Date.now(),deadline:$('#station-mode')?.value==='timed'?Date.now()+420000:null,finished:false};save();render();}
if(b.dataset.saveStation){const c=D.stations.find(c=>c.id===b.dataset.saveStation),checked=[...document.querySelectorAll('[data-station-check]:checked')].map(el=>+el.dataset.stationCheck);S.osce.push({id:c.id,time:Date.now(),checked,total:c.check.length,mode:S.station?.mode});S.station=null;save();toast('Self-assessment saved.');go('osce');}
if(b.dataset.errorAnswer!==undefined){const c=ERROR_CASES[errorIndex],correct=+b.dataset.errorAnswer===c.answer;errorAnswered=true;render();$('#error-feedback').innerHTML=`<div class="feedback"><h3>${correct?'Discrepancy identified.':'Take another look.'}</h3><p>${c.why}</p></div>`;}
if(b.dataset.listen!==undefined){audio.pause();S.audio.index=Number(b.dataset.listen);if(['en','hi'].includes(b.dataset.listenLang))S.audio.lang=b.dataset.listenLang;audioLoaded='';save();go('audio');playAudio();}
if(b.dataset.audioIndex!==undefined){audio.pause();S.audio.index=Number(b.dataset.audioIndex);audioLoaded='';save();render();playAudio();}
if(b.dataset.audioLang){audio.pause();S.audio.lang=b.dataset.audioLang;audioLoaded='';save();render();}
if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);toast('Link copied.');}catch(e){toast('Copy the link from the field above.');}}
switch(a){case 'close':close();break;case 'settings':settings();break;case 'siri':close();siri();break;case 'save-settings':S.theme=$('#setting-theme').value;S.largeText=$('#setting-large').checked;S.goal=Number($('#setting-goal').value);S.examDate=$('#setting-date').value;S.gemini=$('#setting-gemini').checked;save();applyTheme();close();render();toast('Preferences saved.');break;
case 'bookmark':if(S.bookmarks.includes(id))S.bookmarks=S.bookmarks.filter(x=>x!==id);else S.bookmarks.push(id);save();render();toast(S.bookmarks.includes(id)?'Topic saved.':'Bookmark removed.');break;
case 'read':if(S.read[id])delete S.read[id];else S.read[id]=Date.now();save();render();break;
case 'note':modal('Your notes',`<p class="small muted">${esc(lesson(id).title)} · Saved on this device</p><label class="field">Personal study notes<textarea id="lesson-note" data-id="${id}" maxlength="20000" placeholder="What would you like to remember?">${esc(S.notes[id]||'')}</textarea></label><button class="button" data-action="close">Done</button>`);break;
case 'confirm-pending':if(pendingAction){const fn=pendingAction;pendingAction=null;fn();}break;
case 'check-answer':{const s=S.quiz,q=D.questions.find(q=>q.id===s.ids[s.index]);if(s.answers[q.id]!==undefined&&!s.checked[q.id]){record(q,s.answers[q.id]);s.checked[q.id]=true;save();render();}}break;
case 'submit-quiz':submitQuiz();break;case 'flip-card':flashReveal=!flashReveal;render();break;case 'new-exercise':newExercise();$('#exercise-card').innerHTML=exerciseContent();break;case 'next-error':errorIndex=(errorIndex+1)%ERROR_CASES.length;errorAnswered=false;render();break;
case 'finish-station':if(S.station){S.station.finished=true;if(recorder?.state==='recording')recorder.stop();save();render();}break;case 'record':recordVoice();break;case 'delete-recording':if(recordingUrl)URL.revokeObjectURL(recordingUrl);recordingUrl=null;render();break;
case 'audio-play':playAudio();break;case 'audio-prev':changeChapter(-1);break;case 'audio-next':changeChapter(1);break;case 'audio-back':if(audioLoaded)audio.currentTime=Math.max(0,audio.currentTime-15);break;case 'audio-forward':if(audioLoaded)audio.currentTime=Math.min(audio.duration||0,audio.currentTime+15);break;
case 'export':save();exportData();break;case 'reset':pendingAction=()=>{audio.pause();S=fresh();save();applyTheme();$('#province').value=S.province;close();go('home');render();toast('Progress reset.');};close();modal('Reset this device?',`<p>This removes your saved study progress, notes and preferences from this browser. Export a backup first if you want to keep them.</p><div class="button-row"><button class="button danger" data-action="confirm-pending">Reset my progress</button><button class="button secondary" data-action="close">Cancel</button></div>`);break;}
});
window.addEventListener('hashchange',()=>{try{render();window.scrollTo(0,0);main.focus({preventScroll:true});}catch(e){console.error(e);main.innerHTML=notFound();}});
window.addEventListener('pagehide',()=>{if(audioLoaded)S.audio.positions[audioLoaded]=audio.currentTime;save();});
window.addEventListener('offline',()=>toast('You are offline. Saved lessons may still be available. Audio needs a connection unless downloaded.'));
new ResizeObserver(entries=>{document.documentElement.style.setProperty('--dock-height',entries[0].target.getBoundingClientRect().height+'px');}).observe($('.bottom-dock'));
applyTheme();render();if(!storageOK)toast('Saving is unavailable in this browser. Use Settings to export a backup.');
// Structured read/navigation actions use the same visible app state.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [
{name:'search_study_topics',description:'Search the app topic catalogue. Does not change progress.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({query})=>{if(typeof query!=='string'||query.length>200)throw Error('Provide a search query under 200 characters.');return D.lessons.filter(l=>(l.title+' '+l.subject).toLowerCase().includes(query.toLowerCase())).slice(0,20).map(l=>({id:l.id,title:l.title,status:l.status}));}},
{name:'open_study_topic',description:'Navigate to a topic. Opening does not mark it reviewed.',inputSchema:{type:'object',properties:{topicId:{type:'string'}},required:['topicId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({topicId})=>{const l=lesson(topicId);if(!l)throw Error('Unknown topic.');location.hash='lesson/'+l.id;render();return {opened:l.id,status:l.status};}},
{name:'read_study_progress',description:'Read counts of reviewed lessons and practice attempts saved on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({reviewedLessons:available().filter(l=>S.read[l.id]).length,availableLessons:available().length,plannedTopics:D.lessons.length,questionAttempts:S.attempts.length,osceReflections:S.osce.length,province:S.province})}
]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch(e){}}}
})();
